-- first_year_activity
SELECT lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')) AS login,
  countIf(event_type IN ('PushEvent', 'PullRequestEvent', 'IssuesEvent', 'ReleaseEvent')) AS n_act_12m,
  uniqExactIf(lower(actor_login), event_type = 'PushEvent') AS n_pushers_12m
FROM github_events
WHERE lower(if(position(repo_name, '/') > 0, substring(repo_name, 1, position(repo_name, '/') - 1), '')) IN ['openigtlink', 'rdevteam', 'mathezula', 'jusannetworksrl', 'ox-it', 'tantrum', 'mpi-sws-rse', 'yeleman', 'contentone', 'fh-potsdam', 'salimeni', 'mastasj', 'gpo', 'oblac', 'adiungi', 'bopen', 'iron-io', 'ro21han', 'tlx', 'columbiadevelopers', 'ideesculture', 'prooflink', 'python-docs-ko', 'educreations', 'heaps', 'theano', 'fluencyforums', 'igalia', 'redmicainc', 'rotew', 'mixandmatch', 'swp-team-2011-on-charts', 'bulekcosta', 'labelmedia', 'lutraconsulting', 'schultzdk', 'bobah311', 'wowfunhouse', 'taist', 'countersoft', 'shortcast', 'kartverket', 'iomuse', 'angaza', 'geekpark', 'pixeltailgames', 'collection-json', 'abusix', 'commoncrawl', 'eworldrp', 'as4312', 'deshlerlanes', 'crocodoc', 'gsl', 'nauphone', 'ossia', 'moiplabs', 'ticketevolution', 'wireclub', 'independencenumberproject']
